mapper.sql:
FROM		morpheus.AP_HISTORY T1
JOIN		morpheus.AP_USER T2 on T1.USER_NO=T2.USER_NO 
WHERE	 	T1.EVENT_NO = #{eventNo}

mapper.select:
/* AlpineEventDao.selectEventCount */
SELECT CASE WHEN T2.MEMBER_YN='Y' THEN 'Y' ELSE 'N' END AS MEMBER_YN, COUNT(*) AS CNT
GROUP BY CASE WHEN T2.MEMBER_YN='Y' THEN 'Y' ELSE 'N' END ORDER BY T2.MEMBER_YN DESC
